-- Optional: the site upgrades itself automatically. Use this only if your MySQL user cannot ALTER/CREATE.
USE telesom_learnhub;
ALTER TABLE users ADD COLUMN IF NOT EXISTS terms_at DATETIME NULL, ADD COLUMN IF NOT EXISTS notify_email TINYINT NOT NULL DEFAULT 1, ADD COLUMN IF NOT EXISTS notify_sms TINYINT NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS lang VARCHAR(5) NULL;
CREATE TABLE IF NOT EXISTS login_attempts (id INT AUTO_INCREMENT PRIMARY KEY, ip VARCHAR(45) NOT NULL, email VARCHAR(150) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(email), INDEX(ip)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reminders_sent (id INT AUTO_INCREMENT PRIMARY KEY, kind VARCHAR(30) NOT NULL, ref_id INT NOT NULL, user_id INT NOT NULL, sent_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(kind, ref_id, user_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS app_state (k VARCHAR(40) PRIMARY KEY, v VARCHAR(255)) ENGINE=InnoDB;
